sys_script_include.script:
var HSBCClientProcessChecklist = Class.create();
HSBCClientProcessChecklist.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    //MSSRBXCE-18--
    addclientprocesscheclist: function() {
        var clientObj = {};
        var clientProcesschecklist = this.getParameter('sysparm_checklist');

        var gr = new GlideRecord('x_hsb11_hsbc_mss_o_client_and_processes_checklist');
        gr.addQuery('sys_id', clientProcesschecklist);
        gr.query();
        if (gr.next()) {
            clientObj.business_process_definition = gr.getValue('business_process_definition');
            clientObj.client = gr.getValue('client');
            clientObj.active = gr.getDisplayValue('active');

        }
        return JSON.stringify(clientObj);

    },
    duplicaterestriction: function() {
        var status = false;
        var client = this.getParameter('sysparm_client');
        var business = this.getParameter('sysparm_business');

        var gr = new GlideRecord('x_hsb11_hsbc_mss_o_client_and_processes_checklist');
        gr.addEncodedQuery('client=' + client + '^business_process_definition=' + business);
        gr.query();
        if (gr.next()) {
            status = true;
        }
        return status;
    },

    type: 'HSBCClientProcessChecklist '
});
